import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Identify strong candidates using t-test and AUC
    strong_candidates = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] != 'derived':
            t_stat = feats.x[:, i].T @ feats.y / np.sqrt(np.var(feats.x[:, i]) * np.mean(feats.y) * (1 - np.mean(feats.y)))
            auc = feats.x[:, i].T @ feats.y / (np.linalg.norm(feats.x[:, i]) * np.linalg.norm(feats.y))
            strong_candidates.append((fid, abs(t_stat), auc))

    strong_candidates.sort(key=lambda x: x[1], reverse=True)

    # Remove near-duplicates based on correlation
    kept_candidates = []
    correlated_pairs = set()

    # Build correlation matrix
    corr_matrix = np.corrcoef(feats.x.T)

    # Check for correlations >= 0.6
    for i in range(len(feats.ids)):
        for j in range(i+1, len(feats.ids)):
            if abs(corr_matrix[i,j]) >= 0.6:
                correlated_pairs.add((feats.ids[i], feats.ids[j]))

    # Filter out near-duplicates
    seen = set()
    for fid, _, _ in strong_candidates:
        if fid in seen:
            continue
        keep = True
        for kept_fid in kept_candidates:
            if (fid, kept_fid) in correlated_pairs or (kept_fid, fid) in correlated_pairs:
                keep = False
                break
        if keep:
            kept_candidates.append(fid)
            seen.add(fid)

    # If no strong candidates, return empty design
    if not kept_candidates:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Select top 5 as potential drivers
    drivers = kept_candidates[:MAX_DRIVERS]

    # Build columns and products based on correlations
    columns = []
    products = []
    loadings = {}

    # Add main effects
    columns.extend(drivers)

    # Add interaction terms between top drivers
    for i in range(min(len(drivers), 3)):
        for j in range(i+1, min(len(drivers), 3)):
            products.append((drivers[i], drivers[j]))

    # Weighted score: sum of top 3 drivers with weights
    for i, fid in enumerate(drivers[:3]):
        loadings[fid] = 1.0

    # Ensure we don't exceed 4 drivers
    if len(drivers) > 4:
        drivers = drivers[:4]

    return Design(
        drivers=tuple(drivers),
        columns=tuple(columns),
        products=tuple(products),
        loadings=loadings
    )

